import { NotFoundError } from '../../domain/errors/DomainErrors';
import { TaskRepository } from '../../domain/repositories/TaskRepository';
import { TaskAssignmentService } from '../../domain/services/TaskAssignmentService';
import { AssignTaskInput, TaskDto, toTaskDto } from '../dtos/TaskDto';

export class AssignTaskUseCase {
  constructor(
    private readonly tasks: TaskRepository,
    private readonly assignment: TaskAssignmentService,
  ) {}

  async execute(input: AssignTaskInput): Promise<TaskDto> {
    const task = await this.tasks.findById(input.taskId);
    if (task === null) {
      throw new NotFoundError('Task', input.taskId);
    }
    await this.assignment.assign(task, input.userId);
    await this.tasks.save(task);
    return toTaskDto(task);
  }
}

