import { NotFoundError } from '../../domain/errors/DomainErrors';
import { ProjectRepository } from '../../domain/repositories/ProjectRepository';
import { TaskFilter, TaskRepository } from '../../domain/repositories/TaskRepository';
import { TaskStatus } from '../../domain/value-objects/TaskStatus';
import { ListProjectTasksInput, TaskDto, toTaskDto } from '../dtos/TaskDto';

export class ListProjectTasksUseCase {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
  ) {}

  async execute(input: ListProjectTasksInput): Promise<TaskDto[]> {
    const project = await this.projects.findById(input.projectId);
    if (project === null) {
      throw new NotFoundError('Project', input.projectId);
    }

    const filter: TaskFilter = {};
    if (input.status !== undefined) {
      filter.status = TaskStatus.from(input.status);
    }
    if (input.assigneeId !== undefined) {
      filter.assigneeId = input.assigneeId;
    }

    const tasks = await this.tasks.findByProject(project.id, filter);
    return tasks.map(toTaskDto);
  }
}

